settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:wght@400;500;700&family=Inter:wght@400;500;600&display=swap');
.mfp.mfp-brochure-youth{--by-red:#C8102E;--by-ink:#141414;--by-dust:#F5E6E8;--by-line:#e5e7eb;--by-mut:#a8a29e;--by-wash:#f0f0f0;--by-card:#ffffff;font-family:Inter,system-ui,sans-serif;color:var(--by-ink)}
.mfp-brochure-youth,.mfp-brochure-youth *{box-sizing:border-box}
.mfp-brochure-youth .ey-shell{display:grid;grid-template-columns:1fr;min-height:auto;max-width:1152px;margin:0 auto;background:var(--by-wash)}
/* ---------- HERO ---------- */
.mfp-brochure-youth .ey-hero{display:none;position:relative;overflow:hidden;min-height:420px}
.mfp-brochure-youth .ey-hero-media{position:absolute;inset:0}
.mfp-brochure-youth .ey-hero-media img{width:100%;height:100%;object-fit:cover;display:block}
.mfp-brochure-youth .ey-hero-veil{position:absolute;inset:0;background:rgba(20,20,20,.45)}
.mfp-brochure-youth .ey-clip-dark{position:absolute;left:0;right:0;bottom:0;height:60%;background:var(--by-ink);clip-path:polygon(0 25%,100% 0%,100% 100%,0% 100%)}
.mfp-brochure-youth .ey-clip-accent{position:absolute;left:0;right:0;bottom:0;height:62%;background:var(--by-red);clip-path:polygon(0 25%,100% 0%,100% 2.5%,0 27.5%)}
.mfp-brochure-youth .ey-clip-corner{position:absolute;top:0;right:0;width:45%;height:18%;background:var(--by-red);clip-path:polygon(30% 0%,100% 0%,100% 100%,0% 100%)}
.mfp-brochure-youth .ey-hero-inner{position:relative;z-index:10;display:flex;flex-direction:column;justify-content:space-between;height:100%;min-height:360px;padding:32px}
.mfp-brochure-youth .ey-brand{display:flex;align-items:center;justify-content:space-between}
.mfp-brochure-youth .ey-brand-left{display:flex;align-items:center;gap:8px}
.mfp-brochure-youth .ey-brand-icon{display:flex;align-items:center;justify-content:center;width:32px;height:32px;background:#fff;color:var(--by-red)}
.mfp-brochure-youth .ey-brand-icon svg{width:16px;height:16px}
.mfp-brochure-youth .ey-brand-left span{font-family:'DM Sans',Inter,sans-serif;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.2em;color:#fff}
.mfp-brochure-youth .ey-rating{display:inline-flex;align-items:center;gap:4px;border-radius:999px;padding:4px 10px;font-size:11px;font-weight:600;color:#fff;background:rgba(255,255,255,.15)}
.mfp-brochure-youth .ey-rating svg{width:12px;height:12px;color:#fcd34d}
.mfp-brochure-youth .ey-hero-copy{margin-top:auto;padding-bottom:8px}
.mfp-brochure-youth .ey-hero-copy .ey-kicker{font-family:'DM Sans',Inter,sans-serif;margin:0 0 4px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.25em;color:var(--by-red)}
.mfp-brochure-youth .ey-hero h1{font-family:'Bebas Neue',Impact,sans-serif;margin:0;line-height:1;font-size:clamp(3rem,6vw,4.5rem);font-weight:400;letter-spacing:.01em}
.mfp.mfp-brochure-youth .ey-hero h1{color:#fff!important}
.mfp-brochure-youth .ey-hero-copy .ey-sub{margin:12px 0 0;font-size:14px;line-height:1.6;color:rgba(255,255,255,.75)}
.mfp-brochure-youth .ey-stats{display:flex;align-items:center;gap:20px;margin-top:20px}
.mfp-brochure-youth .ey-stats strong{display:block;font-family:'Bebas Neue',Impact,sans-serif;font-size:24px;line-height:1;font-weight:400;color:#fff}
.mfp-brochure-youth .ey-stats span{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.5)}
/* ---------- PANEL ---------- */
.mfp-brochure-youth .ey-panel{display:flex;flex-direction:column;background:var(--by-card);padding:32px 24px}
.mfp-brochure-youth .ey-progress{height:2px;width:100%;overflow:hidden;border-radius:999px;background:var(--by-line);margin-bottom:24px}
.mfp-brochure-youth .ey-progress i{display:block;height:100%;width:25%;background:var(--by-red);transition:width .5s ease}
.mfp-brochure-youth .ey-stepper{display:flex;align-items:flex-start;margin-bottom:32px}
.mfp-brochure-youth .ey-step{display:flex;flex-direction:column;align-items:center;flex:0 0 auto;text-align:center}
.mfp-brochure-youth .ey-dot{display:flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:0;background:var(--by-line);color:#9ca3af;font-size:12px;font-weight:700;transition:all .18s ease}
.mfp-brochure-youth .ey-step.is-active .ey-dot{background:var(--by-ink);color:#fff}
.mfp-brochure-youth .ey-step.is-done .ey-dot{background:var(--by-red);color:#fff}
.mfp-brochure-youth .ey-step-text{margin-top:6px}
.mfp-brochure-youth .ey-step-text strong{display:block;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:#9ca3af}
.mfp-brochure-youth .ey-step.is-active .ey-step-text strong,.mfp-brochure-youth .ey-step.is-done .ey-step-text strong{color:var(--by-ink)}
.mfp-brochure-youth .ey-step-text span{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#9ca3af}
.mfp-brochure-youth .ey-line{flex:1 1 auto;height:1px;margin:16px 8px 0;background:var(--by-line)}
.mfp-brochure-youth .ey-line.is-done{background:var(--by-red)}
/* ---------- CARD / PAGES ---------- */
.mfp-brochure-youth .ey-card{flex:1;background:transparent;padding:0}
.mfp-brochure-youth .ey-page{display:none}
.mfp-brochure-youth .ey-page.is-active{display:block}
.mfp-brochure-youth .ey-page .ey-eyebrow{font-family:'DM Sans',Inter,sans-serif;margin:0 0 2px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.25em;color:var(--by-red)}
.mfp-brochure-youth .ey-page h2{font-family:'Bebas Neue',Impact,sans-serif;margin:0;font-size:2.2rem;line-height:1;font-weight:400;color:var(--by-ink)}
.mfp-brochure-youth .ey-lede{margin:4px 0 28px;font-size:14px;color:var(--by-mut)}
.mfp-brochure-youth .ey-mt5{margin-top:20px}
.mfp-brochure-youth .ey-mt6{margin-top:24px}
.mfp-brochure-youth .ey-grid{display:grid;gap:24px}
.mfp-brochure-youth .ey-grid-2{grid-template-columns:1fr}
/* ---------- FIELDS (underline style) ---------- */
.mfp-brochure-youth .ey-field{display:block}
.mfp-brochure-youth .ey-field>span{display:block;margin-bottom:4px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.1em;color:var(--by-mut)}
.mfp-brochure-youth .mf-field-group{margin:0}
.mfp.mfp-brochure-youth .ey-field .mf-input,.mfp.mfp-brochure-youth .ey-field .mf-select,.mfp.mfp-brochure-youth .ey-field input[type=text],.mfp.mfp-brochure-youth .ey-field input[type=email],.mfp.mfp-brochure-youth .ey-field input[type=tel],.mfp.mfp-brochure-youth .ey-field input[type=number],.mfp.mfp-brochure-youth .ey-field select{width:100%!important;border:0!important;border-bottom:2px solid #d1d5db!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:10px 0!important;font-size:15px!important;color:var(--by-ink)!important;outline:none!important;transition:border-color .18s ease}
.mfp.mfp-brochure-youth .ey-field .mf-input:focus,.mfp.mfp-brochure-youth .ey-field .mf-select:focus,.mfp.mfp-brochure-youth .ey-field input:focus,.mfp.mfp-brochure-youth .ey-field select:focus{border-bottom-color:var(--by-red)!important}
.mfp.mfp-brochure-youth .ey-field .mf-input::placeholder{color:#d6d3d1!important}
.mfp.mfp-brochure-youth .ey-field textarea,.mfp.mfp-brochure-youth .ey-field .mf-textarea{width:100%!important;resize:none!important;border:1px solid var(--by-line)!important;border-radius:0!important;background:#fff!important;box-shadow:none!important;padding:12px 16px!important;font-size:14px!important;color:var(--by-ink)!important;outline:none!important}
.mfp.mfp-brochure-youth .ey-field textarea:focus,.mfp.mfp-brochure-youth .ey-field .mf-textarea:focus{border-color:var(--by-red)!important}
/* MegaForm renders its OWN field label inside .mf-field-group -> hide it (ey-field>span is the label) */
.mfp.mfp-brochure-youth .ey-field .mf-field-label{display:none!important}
.mfp.mfp-brochure-youth .ey-field .mf-field-error{margin-top:4px;font-size:12px;color:var(--by-red)}
.mfp.mfp-brochure-youth .mf-option-control{position:absolute!important;opacity:0!important;width:0!important;height:0!important;pointer-events:none!important}
/* ---- CHIPS: wrap horizontally (override mf-cols grid) ---- */
.mfp.mfp-brochure-youth .mf-option-group--chips{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important;margin-top:8px}
.mfp.mfp-brochure-youth .mf-option-item--chips{margin:0!important;width:auto!important;cursor:pointer}
.mfp.mfp-brochure-youth .mf-option-item--chips .mf-option-ui{display:inline-flex;align-items:center;gap:6px;border:1.5px solid #d1d5db;border-radius:0;background:transparent;padding:6px 14px;font-size:14px;font-weight:500;color:var(--by-ink);box-shadow:none;transition:all .18s ease}
.mfp.mfp-brochure-youth .mf-option-item--chips .mf-option-control:checked+.mf-option-ui{background:var(--by-red);border-color:var(--by-red);color:#fff}
.mfp.mfp-brochure-youth .mf-option-item--chips .mf-option-label{font-weight:500}
/* ---- CARDS: brochure left-bar style ---- */
.mfp.mfp-brochure-youth .mf-option-group--cards{display:grid!important;grid-template-columns:1fr!important;gap:12px!important;margin-top:8px}
.mfp.mfp-brochure-youth .mf-option-item--cards{margin:0!important;cursor:pointer}
.mfp.mfp-brochure-youth .mf-option-item--cards .mf-option-ui{display:flex;align-items:flex-start;gap:16px;border:1px solid var(--by-line);border-left:4px solid transparent;border-radius:0;background:#fff;padding:16px;box-shadow:none;transition:all .18s ease}
.mfp.mfp-brochure-youth .mf-option-item--cards:hover .mf-option-ui{background:#fafafa}
.mfp.mfp-brochure-youth .mf-option-item--cards .mf-option-control:checked+.mf-option-ui{border-color:var(--by-red);border-left-color:var(--by-red);background:var(--by-dust)}
.mfp.mfp-brochure-youth .mf-option-icon{display:flex;align-items:center;justify-content:center;width:40px;height:40px;flex:0 0 40px;background:#f3f4f6;color:#6b7280;font-size:18px}
.mfp.mfp-brochure-youth .mf-option-item--cards .mf-option-control:checked+.mf-option-ui .mf-option-icon{background:var(--by-red);color:#fff}
.mfp.mfp-brochure-youth .mf-option-copy{flex:1}
.mfp.mfp-brochure-youth .mf-option-label{display:block;font-weight:700;color:var(--by-ink)}
.mfp.mfp-brochure-youth .mf-option-desc{display:block;margin-top:2px;font-size:14px;color:#78716c}
.mfp.mfp-brochure-youth .mf-option-badge{align-self:flex-start;border-radius:0;background:var(--by-dust);padding:2px 8px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--by-red)}
.mfp.mfp-brochure-youth .mf-option-check{display:none!important;color:var(--by-red);font-weight:700}
.mfp.mfp-brochure-youth .mf-option-control:checked+.mf-option-ui .mf-option-check{display:inline-flex!important}
/* force the display fonts (theme typography otherwise overrides font-family) */
.mfp.mfp-brochure-youth .ey-hero h1,.mfp.mfp-brochure-youth .ey-page h2,.mfp.mfp-brochure-youth .ey-stats strong{font-family:'Bebas Neue',Impact,'Arial Narrow',sans-serif!important}
.mfp.mfp-brochure-youth .ey-kicker,.mfp.mfp-brochure-youth .ey-page .ey-eyebrow,.mfp.mfp-brochure-youth .ey-brand-left span{font-family:'DM Sans',Inter,sans-serif!important}
/* accommodation = 3 across on desktop */
.mfp.mfp-brochure-youth [data-key='accommodation'] .mf-option-item--cards .mf-option-ui{display:block}
/* ---- plain checkbox rows (scholarship / newsletter / terms) ---- */
.mfp.mfp-brochure-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards){display:grid!important;gap:10px!important;grid-template-columns:none!important;margin-top:6px}
.mfp.mfp-brochure-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-item{cursor:pointer}
.mfp.mfp-brochure-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui{display:flex;align-items:flex-start;gap:10px;font-size:14px;color:#57534e}
.mfp.mfp-brochure-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui::before{content:'';flex:0 0 18px;width:18px;height:18px;margin-top:1px;border:1.5px solid #d1d5db;background:#fff;transition:all .18s ease}
.mfp.mfp-brochure-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-control:checked+.mf-option-ui::before{background:var(--by-red);border-color:var(--by-red);box-shadow:inset 0 0 0 3px #fff}
.mfp.mfp-brochure-youth .ey-grant>span{display:block}
.mfp.mfp-brochure-youth .ey-grant .mf-option-ui{border-left:4px solid var(--by-red);background:var(--by-dust);padding:16px}
/* ---------- REVIEW ---------- */
.mfp-brochure-youth .ey-review{border:1px solid var(--by-line)}
.mfp-brochure-youth .ey-review>div{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;font-size:14px;border-bottom:1px solid #f3f4f6;background:#fff}
.mfp-brochure-youth .ey-review>div:nth-child(even){background:#fafafa}
.mfp-brochure-youth .ey-review>div:last-child{border-bottom:0}
.mfp-brochure-youth .ey-review span{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--by-mut)}
.mfp-brochure-youth .ey-review strong{font-weight:500;color:var(--by-ink)}
/* ---------- ACTIONS ---------- */
.mfp-brochure-youth .ey-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:32px;padding-top:24px;border-top:1px solid var(--by-line)}
.mfp-brochure-youth .ey-back,.mfp-brochure-youth .ey-cancel{display:inline-flex;align-items:center;gap:8px;border:0;background:transparent;padding:10px 16px;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:#d6d3d1;text-decoration:none;cursor:pointer;transition:color .18s ease}
.mfp-brochure-youth .ey-back{color:var(--by-mut)}
.mfp-brochure-youth .ey-back:hover,.mfp-brochure-youth .ey-cancel:hover{color:#57534e}
.mfp-brochure-youth .ey-count{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:#d6d3d1}
.mfp-brochure-youth .ey-next,.mfp-brochure-youth .ey-submit{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:0;background:var(--by-ink);padding:12px 28px;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:#fff;cursor:pointer;transition:opacity .18s ease}
.mfp-brochure-youth .ey-next:hover,.mfp-brochure-youth .ey-submit:hover{opacity:.9}
.mfp-brochure-youth .ey-next:disabled,.mfp-brochure-youth .ey-submit:disabled{opacity:.3;cursor:not-allowed}
.mfp-brochure-youth .mf-form-actions{display:none!important}
/* ---------- RESPONSIVE (hero fluid so the form never gets cramped in narrow panes) ---------- */
@media (min-width:640px){.mfp-brochure-youth .ey-panel{padding:32px 40px}.mfp.mfp-brochure-youth [data-key='accommodation'] .mf-option-group--cards{grid-template-columns:repeat(3,minmax(0,1fr))!important}}
@media (min-width:1024px){.mfp-brochure-youth .ey-shell{grid-template-columns:min(420px,38%) minmax(0,1fr)}.mfp-brochure-youth .ey-hero{display:block}.mfp-brochure-youth .ey-panel{padding:32px 48px}.mfp-brochure-youth .ey-grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* MF-CHECKBOX-ROW-FIX-20260724 */
.mfp.mfp-brochure-youth .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards){display:grid!important;grid-template-columns:minmax(0,1fr)!important}
.mfp.mfp-brochure-youth .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-item{display:block!important;width:100%!important;min-width:0!important}
.mfp.mfp-brochure-youth .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui{display:flex!important;flex-direction:row!important;align-items:flex-start!important;width:100%!important}
.mfp.mfp-brochure-youth .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-copy{flex:1 1 auto!important;min-width:0!important}
.mfp.mfp-brochure-youth .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-label{display:block!important;white-space:normal!important;overflow-wrap:break-word!important;word-break:normal!important}

/* [CardEqualHeight v20260801] Choice cards in a row are laid out on a grid, so each card was only as
   tall as its own copy and a 3-up row came out stepped. Stretch the items and let the option's
   own box fill its track. Scoped to this shell; nothing else in the design changes. */
.mfp.mfp-brochure-youth .mf-option-group--cards{align-items:stretch}
.mfp.mfp-brochure-youth .mf-option-group--cards .mf-option-item{display:flex}
.mfp.mfp-brochure-youth .mf-option-group--cards .mf-option-ui{width:100%;height:100%;box-sizing:border-box}
